@namespace CheckoutWizard.Components

<div class="checkout-wizard">
    @switch (_step)
    {
        case Step.Shipping:
            <ShippingStep Shipping="@_order.Shipping"
                          OnNext="@HandleShippingComplete" />
            break;

        case Step.Payment:
            <PaymentStep Payment="@_order.Payment"
                         OnBack="@(() => _step = Step.Shipping)"
                         OnPlaceOrder="@HandlePlaceOrder" />
            break;
    }
</div>

@code {
    private enum Step { Shipping, Payment }

    [Parameter]
    public EventCallback<Order> OnOrderPlaced { get; set; }

    private readonly Order _order = new();
    private Step _step = Step.Shipping;

    private void HandleShippingComplete()
    {
        _step = Step.Payment;
    }

    private async Task HandlePlaceOrder()
    {
        await OnOrderPlaced.InvokeAsync(_order);
    }
}

@namespace CheckoutWizard.Components
@implements IDisposable
@inject IAddressValidator AddressValidator

<h3>Shipping Information</h3>

<div class="form-group">
    <label>Name</label>
    <input @bind="Shipping.Name" @bind:event="oninput" disabled="@_isValidating" />
</div>

<div class="form-group">
    <label>Address</label>
    <input @bind="Shipping.Address" @bind:event="oninput"
           @oninput="@(_ => _fieldsDirty = true)" disabled="@_isValidating" />
</div>

<div class="form-group">
    <label>City</label>
    <input @bind="Shipping.City" @bind:event="oninput"
           @oninput="@(_ => _fieldsDirty = true)" disabled="@_isValidating" />
</div>

<div class="form-group">
    <label>Zip Code</label>
    <input @bind="Shipping.ZipCode" @bind:event="oninput"
           @oninput="@(_ => _fieldsDirty = true)" disabled="@_isValidating" />
</div>

@if (_validationError is not null)
{
    <div class="validation-error">@_validationError</div>
}

<button disabled="@_isValidating" @onclick="HandleNext">
    @if (_isValidating)
    {
        <span class="spinner" aria-hidden="true"></span>
        <span>Validating…</span>
    }
    else
    {
        <span>Next</span>
    }
</button>

@code {
    [Parameter, EditorRequired]
    public ShippingInfo Shipping { get; set; } = default!;

    [Parameter]
    public EventCallback OnNext { get; set; }

    private CancellationTokenSource? _cts;
    private bool _isValidating;
    private bool _fieldsDirty;
    private string? _validationError;

    private async Task HandleNext()
    {
        if (string.IsNullOrWhiteSpace(Shipping.Address) ||
            string.IsNullOrWhiteSpace(Shipping.City) ||
            string.IsNullOrWhiteSpace(Shipping.ZipCode))
        {
            _validationError = "Address, City, and Zip Code are required.";
            return;
        }

        // Cancel any in-flight validation (e.g. user went back, changed fields, clicked Next again)
        CancelPendingValidation();

        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        _isValidating = true;
        _fieldsDirty = false;
        _validationError = null;

        try
        {
            var isValid = await AddressValidator.ValidateAddressAsync(
                Shipping.Address, Shipping.City, Shipping.ZipCode, token);

            token.ThrowIfCancellationRequested();

            if (isValid)
            {
                await OnNext.InvokeAsync();
            }
            else
            {
                _validationError = "The address could not be verified. Please check and try again.";
            }
        }
        catch (OperationCanceledException)
        {
            // Validation was intentionally cancelled — nothing to do.
        }
        finally
        {
            _isValidating = false;
        }
    }

    private void CancelPendingValidation()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }

    public void Dispose()
    {
        CancelPendingValidation();
    }
}

